import { mode } from './mode.js';
export function load(input) {
  const errors = [];
  const ids = new Set();
  for (const row of input.items) {
    ids.add(row.id);
  }
  const data = { count: count(input.count), rules: rules(input.rules, errors), mode: mode(input.mode, errors) };
  return { ok: errors.length === 0, ids: [...ids], data, errors };
}

