export function rules(rows, errors) {
  const result = [];
  const header = rows.findIndex(row => row[0] === 'Rule ID');
  if (header < 0) { errors.push('missing rule header'); return result; }
  for (const [code, label] of rows.slice(header + 1)) {
    if (!code && !label) break;
    if (!/^R\d{2}$/.test(code)) { errors.push('invalid rule code'); continue; }
    result.push({ code, label });
  }
  return result;
}

